import ast, operator

_ALLOWED = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv, ast.Pow: operator.pow, ast.USub: operator.neg}

def _eval(node):
    if isinstance(node, ast.Num): return node.n
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)): return node.value
    if isinstance(node, ast.BinOp): return _ALLOWED[type(node.op)](_eval(node.left), _eval(node.right))
    if isinstance(node, ast.UnaryOp): return _ALLOWED[type(node.op)](_eval(node.operand))
    raise ValueError(f'unsupported node: {type(node).__name__}')

def calc(expression: str):
    return _eval(ast.parse(expression, mode='eval').body)

def lookup_constant(name: str):
    return {'pi': 3.141592653589793, 'e': 2.718281828459045, 'g': 9.80665}.get(name)

# Deterministic mock LLM. Returns the next action given the current state.
# `state` is { 'question': str, 'history': [{'tool': str, 'input': ..., 'output': ...}], 'self_check_phase': bool }

def next_action(state):
    q = state['question'].lower()
    if state.get('self_check_phase'):
        # Verify the answer
        last = state['history'][-1] if state['history'] else None
        return { 'type': 'self_check', 'verdict': 'pass' if last else 'skipped' }

    if '2+2' in q.replace(' ', ''):
        if not state['history']:
            return { 'type': 'tool', 'tool': 'calc', 'input': '2+2' }
        return { 'type': 'final', 'answer': str(state['history'][-1]['output']) }

    if 'pi' in q and 'times' in q:
        # ex: 'pi times 2'
        if not any(h['tool'] == 'lookup_constant' for h in state['history']):
            return { 'type': 'tool', 'tool': 'lookup_constant', 'input': 'pi' }
        if not any(h['tool'] == 'calc' for h in state['history']):
            pi = next(h['output'] for h in state['history'] if h['tool'] == 'lookup_constant')
            return { 'type': 'tool', 'tool': 'calc', 'input': f'{pi}*2' }
        return { 'type': 'final', 'answer': str(state['history'][-1]['output']) }

    # Loop trap — keep asking for the same tool
    return { 'type': 'tool', 'tool': 'calc', 'input': '1+1' }

