import sys
from tools import calc, lookup_constant
import mock_llm

MAX_STEPS = 6

TOOLS = {'calc': calc, 'lookup_constant': lookup_constant}

def _execute(tool, inp):
    fn = TOOLS.get(tool)
    if not fn: return {'error': f'unknown tool {tool}'}
    try:
        return fn(inp)
    except Exception as e:
        return {'error': str(e)}

def solve(question: str):
    state = { 'question': question, 'history': [], 'self_check_phase': False }
    tool_calls = []
    final_answer = None
    self_check = 'skipped'
    last_call_sig = None
    for step in range(MAX_STEPS):
        action = mock_llm.next_action(state)
        if action.get('type') == 'final':
            final_answer = action.get('answer', '')
            break
        if action.get('type') == 'tool':
            tool = action['tool']
            inp = action['input']
            sig = (tool, inp)
            if sig == last_call_sig:
                self_check = 'fail'
                final_answer = 'loop_detected'
                break
            last_call_sig = sig
            out = _execute(tool, inp)
            tool_calls.append({ 'tool': tool, 'input': inp, 'output': out })
            state['history'].append({ 'tool': tool, 'input': inp, 'output': out })
            continue
        break

    if final_answer is None:
        final_answer = 'max_steps_reached'
        self_check = 'fail'

    if self_check == 'skipped' and final_answer not in ('loop_detected', 'max_steps_reached'):
        verify_state = { **state, 'self_check_phase': True }
        verdict = mock_llm.next_action(verify_state)
        if verdict.get('type') == 'self_check':
            self_check = verdict.get('verdict', 'skipped')

    return {
        'final_answer': final_answer,
        'tool_calls': tool_calls,
        'iterations': len(tool_calls),
        'self_check': self_check,
    }

if __name__ == '__main__':
    print(solve(' '.join(sys.argv[1:])))

